"""Search-based oracle: picks the rounded result by neighbour search over the
format's value grid, and encodes it by dictionary lookup (no field arithmetic)."""
from fractions import Fraction
import math

TWO = Fraction(2)

class Format:
    def __init__(self, ebits, fbits):
        self.ebits, self.fbits = ebits, fbits
        self.width = 1 + ebits + fbits
        self.bias = 2**(ebits-1) - 1
        self.F = 2**fbits
        self.Eall = 2**ebits - 1
        self.emin = 1 - self.bias
        self.emax = self.Eall - 1 - self.bias
        self.subq = TWO**(self.emin - fbits)     # subnormal quantum
        self.maxfin = (2*self.F - 1) * TWO**(self.emax - fbits)
        # dictionary of every finite encoding -> exact value (toy formats)
        self.enc = {}
        for e in range(self.Eall):
            for f in range(self.F):
                if e == 0:
                    v = Fraction(f) * self.subq
                else:
                    v = Fraction(self.F + f) * TWO**(e - self.bias - fbits)
                self.enc[v] = (e << fbits) | f
        self.enc[Fraction(0)] = 0
        self.sorted_vals = sorted(self.enc)
    def bits(self, s, e, f):
        return (s << (self.width-1)) | (e << self.fbits) | f
    def decode(self, v):
        s = (v >> (self.width-1)) & 1
